insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('b01', 'basic', 1, 'linear-system', '設 $A$ 為 $3\times 4$ 矩陣且 $\operatorname{rank}(A)=3$。對任意 $\mathbf b\in\mathbb R^3$,方程組 $A\mathbf x=\mathbf b$ 的解為何?', '[{"id":"o1","text":"必有無窮多組解"},{"id":"o2","text":"可能無解"},{"id":"o3","text":"恰有一組解"},{"id":"o4","text":"解的個數不一定"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('b02', 'basic', 2, 'inverse', '設 $A$ 為 $n\times n$ 矩陣。下列何者「不是」$A$ 可逆的等價條件?', '[{"id":"o1","text":"$A$ 的特徵值全為 $1$"},{"id":"o2","text":"$\\det A\\neq 0$"},{"id":"o3","text":"$A$ 的行向量線性獨立"},{"id":"o4","text":"$A\\mathbf x=\\mathbf 0$ 只有零解"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('b03', 'basic', 2, 'inverse', '設 $A,B$ 皆為 $n\times n$ 可逆矩陣。下列何者「恆成立」?', '[{"id":"o1","text":"$(AB)^{-1}=B^{-1}A^{-1}$"},{"id":"o2","text":"$(AB)^{-1}=A^{-1}B^{-1}$"},{"id":"o3","text":"$(AB)^{-1}=A^{T}B^{T}$"},{"id":"o4","text":"$(A+B)^{-1}=A^{-1}+B^{-1}$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('b04', 'basic', 3, 'subspace', '下列哪一個集合是 $\mathbb R^3$ 的子空間?', '[{"id":"o1","text":"$\\{(x,y,z): x=2y\\}$"},{"id":"o2","text":"$\\{(x,y,z): x+y+z=1\\}$"},{"id":"o3","text":"$\\{(x,y,z): xy=0\\}$"},{"id":"o4","text":"$\\{(x,y,z): z\\ge 0\\}$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('b05', 'basic', 4, 'span-dim', '令 $\mathbf v_1=(1,2,3),\ \mathbf v_2=(2,4,6),\ \mathbf v_3=(0,1,1)$,則 $\dim\operatorname{span}\{\mathbf v_1,\mathbf v_2,\mathbf v_3\}$ 為何?', '[{"id":"o1","text":"$2$"},{"id":"o2","text":"$1$"},{"id":"o3","text":"$3$"},{"id":"o4","text":"$0$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('b06', 'basic', 5, 'rank-nullity', '設 $A$ 為 $4\times 6$ 矩陣且 $\operatorname{rank}(A)=3$,則 $\dim\ker(A)$(零度)為何?', '[{"id":"o1","text":"$3$"},{"id":"o2","text":"$1$"},{"id":"o3","text":"$2$"},{"id":"o4","text":"$4$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('b07', 'basic', 6, 'det-properties', '設 $A$ 為 $3\times3$ 矩陣且 $\det A=2$,則 $\det(3A)$ 為何?', '[{"id":"o1","text":"$54$"},{"id":"o2","text":"$6$"},{"id":"o3","text":"$18$"},{"id":"o4","text":"$162$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('b08', 'basic', 7, 'eigen-basic', '上三角矩陣 $\begin{bmatrix}2&1\\0&3\end{bmatrix}$ 的特徵值為何?', '[{"id":"o1","text":"$2$ 與 $3$"},{"id":"o2","text":"$1$ 與 $2$"},{"id":"o3","text":"$1$ 與 $3$"},{"id":"o4","text":"$3$ 與 $6$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('b09', 'basic', 8, 'symmetric-spectral', '設 $A$ 為實對稱矩陣。對應到「不同特徵值」的特徵向量必定:', '[{"id":"o1","text":"互相正交"},{"id":"o2","text":"互相平行"},{"id":"o3","text":"線性相依"},{"id":"o4","text":"皆為單位向量"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('c01', 'chapter', 6, 'det-properties', '設 $3\times3$ 矩陣 $A$ 的列向量為 $R_1,R_2,R_3$,且 $\det A=5$。令 $B$ 的列依序為 $R_2,\ R_1,\ R_1+R_3$,則 $\det B$ 為何?', '[{"id":"o1","text":"$-5$"},{"id":"o2","text":"$5$"},{"id":"o3","text":"$10$"},{"id":"o4","text":"$0$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('c02', 'chapter', 7, 'eigen-basic', '矩陣 $A=\begin{bmatrix}4&1\\2&3\end{bmatrix}$ 的特徵值為何?', '[{"id":"o1","text":"$2$ 與 $5$"},{"id":"o2","text":"$1$ 與 $6$"},{"id":"o3","text":"$3$ 與 $4$"},{"id":"o4","text":"$-2$ 與 $-5$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('c03', 'chapter', 7, 'diagonalizable', '下列哪一個矩陣「不可」對角化?', '[{"id":"o1","text":"$\\begin{bmatrix}1&1\\\\0&1\\end{bmatrix}$"},{"id":"o2","text":"$\\begin{bmatrix}2&0\\\\0&2\\end{bmatrix}$"},{"id":"o3","text":"$\\begin{bmatrix}1&2\\\\2&1\\end{bmatrix}$"},{"id":"o4","text":"$\\begin{bmatrix}0&1\\\\1&0\\end{bmatrix}$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('c04', 'chapter', 7, 'eigen-functions', '設 $3\times3$ 矩陣 $A$ 的特徵值為 $1,2,3$,則 $\operatorname{tr}(A^3)$ 為何?', '[{"id":"o1","text":"$36$"},{"id":"o2","text":"$6$"},{"id":"o3","text":"$14$"},{"id":"o4","text":"$216$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('c05', 'chapter', 8, 'projection', '將 $\mathbf b=(1,2,3)$ 正交投影到 $\mathbf a=(1,1,1)$ 所張成的直線,投影向量為何?', '[{"id":"o1","text":"$(2,2,2)$"},{"id":"o2","text":"$(1,2,3)$"},{"id":"o3","text":"$(6,6,6)$"},{"id":"o4","text":"$(1,1,1)$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('c06', 'chapter', 8, 'orthogonal-matrix', '設 $Q$ 為實正交矩陣($Q^TQ=I$),則 $\det Q$ 可能為何?', '[{"id":"o1","text":"$1$ 或 $-1$"},{"id":"o2","text":"只能是 $1$"},{"id":"o3","text":"只能是 $-1$"},{"id":"o4","text":"任意實數"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('h01', 'homework', 7, 'idempotent', '設 $A$ 為 $n\times n$ 實矩陣且 $A^2=A$。下列何者「必為真」?', '[{"id":"o1","text":"$A$ 的特徵值只可能是 $0$ 或 $1$"},{"id":"o2","text":"$A=I$ 或 $A=0$"},{"id":"o3","text":"$A$ 必可逆"},{"id":"o4","text":"$\\det A=1$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('h02', 'homework', 5, 'rank-ineq', '設 $A,B$ 為 $n\times n$ 矩陣且 $AB=0$。下列何者「必成立」?', '[{"id":"o1","text":"$\\operatorname{rank}A+\\operatorname{rank}B\\le n$"},{"id":"o2","text":"$A=0$ 或 $B=0$"},{"id":"o3","text":"$BA=0$"},{"id":"o4","text":"$A$ 與 $B$ 皆不可逆"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('h03', 'homework', 3, 'dim-formula', '設 $U,W$ 皆為 $\mathbb R^4$ 的 3 維子空間,則 $\dim(U\cap W)$ 至少為何?', '[{"id":"o1","text":"$2$"},{"id":"o2","text":"$0$"},{"id":"o3","text":"$1$"},{"id":"o4","text":"$3$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('h04', 'homework', 6, 'skew-symmetric', '設 $A$ 為 $3\times3$ 實矩陣且 $A^T=-A$。下列何者正確?', '[{"id":"o1","text":"$\\det A=0$"},{"id":"o2","text":"$A$ 必可逆"},{"id":"o3","text":"$A$ 的特徵值必為實數"},{"id":"o4","text":"$A^2=0$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.questions (id, kind, chapter, concept_id, prompt, options, origin, source_ref) values ('h05', 'homework', 5, 'gram-matrix', '設 $A$ 為 $m\times n$ 實矩陣。下列何者恆等於 $\operatorname{rank}(A^TA)$?', '[{"id":"o1","text":"$\\operatorname{rank}(A)$"},{"id":"o2","text":"$m$"},{"id":"o3","text":"$n$"},{"id":"o4","text":"$\\operatorname{rank}(A)^2$"}]'::jsonb, 'self-authored', null) on conflict (id) do update set kind = excluded.kind, chapter = excluded.chapter, concept_id = excluded.concept_id, prompt = excluded.prompt, options = excluded.options, origin = excluded.origin, source_ref = excluded.source_ref;
insert into public.question_keys (question_id, correct_option_id, explanation) values ('b01', 'o1', 'rank 等於列數 3,所以 $A$ 的行空間就是 $\mathbb R^3$,任何 $\mathbf b$ 都在其中,方程組必有解。未知數 4 個、秩 3,自由變數有 $4-3=1$ 個,因此有無窮多組解。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('b02', 'o1', '可逆等價於 $\det A\ne0$、行(列)向量線性獨立、$A\mathbf x=\mathbf 0$ 只有零解,以及特徵值「全不為 0」。特徵值全為 1 只是其中一種特例,不是等價條件(例如 $\operatorname{diag}(2,3)$ 可逆但特徵值不是 1)。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('b03', 'o1', '驗證 $(AB)(B^{-1}A^{-1})=A(BB^{-1})A^{-1}=I$,所以反矩陣要「反序」。$A^{-1}B^{-1}$ 只有在 $A,B$ 可交換時才相等,和的反矩陣則沒有任何類似公式。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('b04', 'o1', '子空間必須含零向量並對加法、純量乘法封閉。$x=2y$ 是齊次線性條件,封閉。$x+y+z=1$ 不含零向量;$xy=0$ 對加法不封閉($(1,0,0)+(0,1,0)=(1,1,0)$);$z\ge0$ 對負純量乘法不封閉。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('b05', 'o1', '$\mathbf v_2=2\mathbf v_1$,所以 $\mathbf v_2$ 是多餘的;而 $\mathbf v_3$ 不是 $\mathbf v_1$ 的倍數,與它獨立。因此生成空間維度為 2。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('b06', 'o1', '秩—零度定理:$\operatorname{rank}(A)+\operatorname{nullity}(A)=n$,其中 $n$ 是「行數」(未知數個數)6。所以零度為 $6-3=3$。常見錯誤是誤用列數 4。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('b07', 'o1', '每一列都乘 3,共提出 $3^3$,所以 $\det(3A)=3^3\det A=27\cdot2=54$。注意是 $3^n$ 而不是 $3$。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('b08', 'o1', '三角矩陣的特徵值就是對角線元素。也可由 $\det(A-\lambda I)=(2-\lambda)(3-\lambda)$ 得到。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('b09', 'o1', '若 $A\mathbf u=\lambda\mathbf u,\ A\mathbf v=\mu\mathbf v$,則 $\lambda\,\mathbf u\cdot\mathbf v=A\mathbf u\cdot\mathbf v=\mathbf u\cdot A\mathbf v=\mu\,\mathbf u\cdot\mathbf v$。$\lambda\ne\mu$ 推得 $\mathbf u\cdot\mathbf v=0$。長度則可以任意縮放。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('c01', 'o1', '先把第 3 列的 $R_1$ 消掉(加上某列的倍數,行列式不變),得 $\det(R_2,R_1,R_3)$。再交換前兩列,符號變號,得 $-\det(R_1,R_2,R_3)=-5$。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('c02', 'o1', '$\operatorname{tr}A=7,\ \det A=10$,特徵方程式為 $\lambda^2-7\lambda+10=0$,所以 $\lambda=2,5$。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('c03', 'o1', '$\begin{bmatrix}1&1\\0&1\end{bmatrix}$ 只有特徵值 1(代數重數 2),但 $A-I$ 的秩為 1,特徵空間維度只有 1(幾何重數 1),湊不出兩個獨立特徵向量。其餘三個矩陣不是已經對角,就是實對稱,皆可對角化。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('c04', 'o1', '$A^3$ 的特徵值是 $1^3,2^3,3^3$,而跡等於特徵值之和:$1+8+27=36$。$14$ 是 $\operatorname{tr}(A^2)$;$216=(\operatorname{tr}A)^3$ 是常見誤用。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('c05', 'o1', '$\operatorname{proj}_{\mathbf a}\mathbf b=\dfrac{\mathbf a\cdot\mathbf b}{\mathbf a\cdot\mathbf a}\mathbf a=\dfrac{6}{3}(1,1,1)=(2,2,2)$。$(6,6,6)$ 是忘了除以 $\mathbf a\cdot\mathbf a$。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('c06', 'o1', '$\det(Q^TQ)=(\det Q)^2=1$,所以 $\det Q=\pm1$。兩者皆會出現:單位矩陣為 $+1$,鏡射矩陣為 $-1$。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('h01', 'o1', '若 $A\mathbf v=\lambda\mathbf v,\ \mathbf v\ne\mathbf 0$,則 $\lambda\mathbf v=A\mathbf v=A^2\mathbf v=\lambda^2\mathbf v$,故 $\lambda^2=\lambda$,即 $\lambda\in\{0,1\}$。投影矩陣是反例:它冪等,但既不是 $I$ 或 $0$,也不可逆(除非是 $I$)。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('h02', 'o1', '$AB=0$ 表示 $B$ 的行空間包含於 $\ker A$,故 $\operatorname{rank}B\le n-\operatorname{rank}A$。矩陣乘法有零因子,所以不一定有一個為 0(例如 $A=B=\begin{bmatrix}0&1\\0&0\end{bmatrix}$);$BA$ 也不一定是 0;若 $A$ 可逆,則 $B=0$,此時 $A$ 仍可逆,所以「皆不可逆」也不成立。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('h03', 'o1', '由 $\dim(U+W)=\dim U+\dim W-\dim(U\cap W)$ 及 $\dim(U+W)\le4$,得 $\dim(U\cap W)\ge 3+3-4=2$。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('h04', 'o1', '$\det A=\det A^T=\det(-A)=(-1)^3\det A=-\det A$,所以 $\det A=0$(奇數階才有此結果)。斜對稱矩陣的特徵值是 0 或純虛數,$A^2=0$ 也不一定成立。');
insert into public.question_keys (question_id, correct_option_id, explanation) values ('h05', 'o1', '$A^TA\mathbf x=\mathbf 0\Rightarrow\mathbf x^TA^TA\mathbf x=\|A\mathbf x\|^2=0\Rightarrow A\mathbf x=\mathbf 0$,所以 $\ker(A^TA)=\ker A$,兩者零度相同,秩也相同。$n$ 只有在 $A$ 行滿秩時才相等。');
